import DisplayDomain
import Foundation

/// Where an ICC profile file lives, which decides what it is and what OpenDisplay may do with it.
/// Profiles are identified by file (standardized path), never by their description: two files can
/// carry the same name and are still different profiles.
public enum ICCProfileProvenance: String, Hashable, Sendable, CaseIterable {
    /// Generated by macOS for a display: the display's own factory profile, or one in the shared
    /// `/Library/ColorSync/Profiles/Displays` folder.
    case factory
    /// Ships with macOS (`/System/Library/ColorSync`).
    case system
    /// In the user's own `~/Library/ColorSync/Profiles` folder: the user's copy, which OpenDisplay
    /// may import into and remove from.
    case user
    /// Installed for every user of this Mac (`/Library/ColorSync/Profiles`, outside `Displays`).
    case shared
    /// Anywhere else — inside an app, on another volume.
    case other
}

/// The classification, removal and import-naming rules for ICC profile files, plus a reader for
/// the 128-byte ICC header. Pure (paths and bytes in, values out); the app does the file and
/// ColorSync work. Kept in step with `ColorProfileGuard.classify`, which decides the gamma
/// safeguard from the same folders.
public enum ICCProfileCatalog {
    static let systemFolder = "/System/Library/ColorSync/"
    static let sharedFolder = "/Library/ColorSync/Profiles/"
    static let sharedDisplaysFolder = "/Library/ColorSync/Profiles/Displays/"

    /// The file-name extensions of ICC profiles OpenDisplay imports.
    public static let fileExtensions: Set<String> = ["icc", "icm"]

    /// What a profile file is. `factoryPaths` are the display's own factory profiles as ColorSync
    /// reports them; `userFolder` is `~/Library/ColorSync/Profiles` for the current user.
    public static func provenance(of path: String, factoryPaths: [String], userFolder: String) -> ICCProfileProvenance {
        let path = standardized(path)
        if path.hasPrefix(systemFolder) { return .system }
        if factoryPaths.contains(where: { standardized($0) == path }) || path.hasPrefix(sharedDisplaysFolder) {
            return .factory
        }
        if isInside(path, folder: userFolder) { return .user }
        if path.hasPrefix(sharedFolder) { return .shared }
        return .other
    }

    /// How the gamma safeguard treats a profile of this provenance (`ColorProfileGuard`): factory
    /// and system profiles are safe; any other assigned profile is a custom one.
    public static func guardAssignment(for provenance: ICCProfileProvenance) -> ColorProfileGuard.Assignment {
        switch provenance {
        case .factory: return .factory
        case .system: return .system
        case .user, .shared, .other: return .custom
        }
    }

    /// Whether OpenDisplay may move a profile of this provenance to the Trash: only the user's own
    /// copies. Shared, system and factory files belong to macOS or an administrator and removing
    /// them needs their authorization, which OpenDisplay doesn't ask for.
    public static func isRemovable(_ provenance: ICCProfileProvenance) -> Bool {
        provenance == .user
    }

    /// Whether a file name looks like an ICC profile OpenDisplay can import.
    public static func isProfileFileName(_ name: String) -> Bool {
        fileExtensions.contains((name as NSString).pathExtension.lowercased())
    }

    /// The file name an imported copy takes in the user folder: the source name, or — when that name
    /// is taken (compared case-insensitively, as the default APFS volume does) — the same name with
    /// the first free " 2", " 3", … before the extension. The existing file is never overwritten.
    public static func importFileName(for sourceName: String, existing: Set<String>) -> String {
        let taken = Set(existing.map { $0.lowercased() })
        guard taken.contains(sourceName.lowercased()) else { return sourceName }
        let base = (sourceName as NSString).deletingPathExtension
        let ext = (sourceName as NSString).pathExtension
        var number = 2
        while true {
            let candidate = ext.isEmpty ? "\(base) \(number)" : "\(base) \(number).\(ext)"
            if !taken.contains(candidate.lowercased()) { return candidate }
            number += 1
        }
    }

    private static func standardized(_ path: String) -> String {
        URL(fileURLWithPath: path).standardizedFileURL.path
    }

    private static func isInside(_ path: String, folder: String) -> Bool {
        let folder = standardized(folder)
        let prefix = folder.hasSuffix("/") ? folder : folder + "/"
        return path.hasPrefix(prefix)
    }
}

/// The fixed 128-byte header every ICC profile starts with (ICC.1 §7.2): what kind of device the
/// profile describes, the colour space of its data, and the version it was written for.
public struct ICCProfileHeader: Hashable, Sendable {
    /// Profile/device class signature, e.g. "mntr" (display), "spac" (colour space), "prtr".
    public let deviceClass: String
    /// Data colour space signature, e.g. "RGB", "GRAY", "CMYK" (padding removed).
    public let colorSpace: String
    /// Profile connection space, "XYZ" or "Lab".
    public let connectionSpace: String
    /// "major.minor" or "major.minor.bugfix", e.g. "4.3" or "2.1".
    public let version: String
    /// When the profile was created, if the header's date is a real one (UTC).
    public let created: Date?
    /// The creating vendor's signature, when set.
    public let creator: String?

    /// Parses a header; nil when there are fewer than 128 bytes or the 'acsp' signature is missing.
    public init?(bytes: [UInt8]) {
        guard bytes.count >= 128, Self.signature(bytes, 36) == "acsp" else { return nil }
        deviceClass = Self.signature(bytes, 12)
        colorSpace = Self.signature(bytes, 16)
        connectionSpace = Self.signature(bytes, 20)
        let major = Int(bytes[8])
        let minor = Int(bytes[9] >> 4)
        let bugfix = Int(bytes[9] & 0x0F)
        version = bugfix == 0 ? "\(major).\(minor)" : "\(major).\(minor).\(bugfix)"
        created = Self.date(bytes, 24)
        let creator = Self.signature(bytes, 80)
        self.creator = creator.isEmpty ? nil : creator
    }

    /// A display profile ("mntr"), as opposed to one describing a colour space, printer or scanner.
    public var isDisplayClass: Bool { deviceClass == "mntr" }
    public var isRGB: Bool { colorSpace == "RGB" }

    /// A four-character signature with its space padding (and any NULs) removed.
    private static func signature(_ bytes: [UInt8], _ offset: Int) -> String {
        let scalars = bytes[offset..<offset + 4].filter { $0 != 0 }.map { Character(Unicode.Scalar($0)) }
        return String(scalars).trimmingCharacters(in: .whitespaces)
    }

    private static func date(_ bytes: [UInt8], _ offset: Int) -> Date? {
        func field(_ index: Int) -> Int { Int(bytes[offset + 2 * index]) << 8 | Int(bytes[offset + 2 * index + 1]) }
        var components = DateComponents()
        components.year = field(0)
        components.month = field(1)
        components.day = field(2)
        components.hour = field(3)
        components.minute = field(4)
        components.second = field(5)
        guard let year = components.year, year > 0, let month = components.month, (1...12).contains(month),
              let day = components.day, (1...31).contains(day) else { return nil }
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: "UTC") ?? calendar.timeZone
        return calendar.date(from: components)
    }
}
